/**
 * `up --wait` fails with nothing but an exit code, and Docker's own line is only "dependency failed
 * to start". Naming the container and where to look turns a dead end into a next step — this exact
 * message cost a user two debugging rounds.
 */
async function startAndWait(instance, options) {
  try {
    await runStep({
      pending: 'Starting containers and waiting for health',
      done: 'Started containers',
      logFile: logFileFor(instance, 'containers-start'),
      run: (logFile) => composeCaptured(instance, composeUpArgs(options), { logFile }),
    });
  } catch (error) {
    const stuck = await unhealthyServices(instance, run);
    if (stuck.length > 0) {
      const named = stuck.map(({ service, status }) => `  ${service} (${status})`).join('\n');
      throw new Error(
        `${error.message}\n\nNot healthy yet:\n${named}\n\n` +
          `Look at what it is doing: just logs ${stuck[0].service}\n` +
          `A cold start can be slow; re-running just up picks up where this left off.`,
      );
    } else {
      throw error;
    }
  }
}

export async function main(argv) {
  const options = parseArgs(argv);
  const proxyPort = Number(process.env.URBO_PROXY_PORT ?? 80);

  const checks = await runChecks({ proxyPort, env: process.env, exec: run });
  console.log(formatReport(checks));
  if (!checks.every((check) => check.ok)) {
    console.error('\nPreflight failed. Fix the items above, or run `just doctor` again.');
    return 1;
  }

  const instance = await resolveIdentifier({
    repoRoot: REPO_ROOT,
    envValue: process.env.URBO_INSTANCE ?? null,
    prompt: askTerminal,
  });
  console.log(`\nInstance: ${instance}`);

  // Validate the app selection before anything expensive happens.
  selectDevServers(options.apps);

  const stateDir = stateDirFor(instance);
  const envFile = envFileFor(instance);
  const seededMarker = seededMarkerFor(instance);
  const realmHashMarker = realmHashMarkerFor(instance);

  // A Ctrl-C during the very first `compose up`, a failed seeder, or a `--no-seed` first run all
  // leave the volume present but the database unseeded. Gating on the volume's existence alone (as
  // this used to) made that state unrecoverable: the next `just up` would see the volume and skip
  // seeding forever. The marker is the only trustworthy signal — it is written after the seeder
  // exits 0, so its absence always means "never successfully seeded".
  const databaseIsFresh = options.fresh || !existsSync(seededMarker);
  // Asked here, right after the instance, so that both questions are answered before the minutes of
  // installing and building start and the developer can walk away.
  const seedDecision = await resolveSeedDecision({
    seed: options.seed,
    databaseIsFresh,
    interactive: process.stdin.isTTY === true && process.stdout.isTTY === true,
    prompt: askTerminal,
  });
  if (seedDecision === INTERRUPTED) {
    // Nothing has started yet, so there is nothing to stop.
    return 130;
  }
  const steps = databaseSteps({ databaseIsFresh, willSeed: seedDecision });

  if (options.fresh) {
    clearFreshState({ seededMarker, realmHashMarker });
    if (existsSync(envFile)) {
      // The shared proxy still holds an endpoint on this instance's network — detach before
      // asking Docker to delete it, exactly like `reset` does. Skipping this asks Docker to
      // delete a network with a live endpoint: at best it warns and leaks the network, at worst
      // compose exits non-zero and `--fresh` fails outright.
      await detachInstance({ instance, exec: run });
      await compose(instance, ['down', '-v']);
    }
  }

  const ports = await resolveDevServerPorts(stateDir);
  const { renderedRealm } = await renderAll({ repoRoot: REPO_ROOT, instance, proxyPort });

  if (steps.checkRealmDrift) {
    // Exactly when Keycloak's database (the same `urbo-cms-data` volume the seeded marker already
    // reasons about) survives from an earlier run — the one condition under which
    // `start-dev --import-realm` silently keeps the realm already in there instead of picking up
    // what was just rendered (see `realm-drift.mjs`). Check before doing anything expensive (pnpm
    // install, the backend image build): a stale realm always means broken login, so there is
    // nothing to gain from discovering that four minutes later.
    const outcome = compareRealmHash({
      storedHash: readStoredRealmHash(instance),
      freshHash: hashRealm(renderedRealm),
    });
    if (outcome === 'drift') {
      throw new Error(realmDriftMessage(instance));
    } else if (outcome === 'bootstrap') {
      // No baseline recorded yet for this instance (predates this check, or `--fresh` cleared it on
      // a run that then failed before reaching the write below). Nothing to compare against, so
      // trust what is presumably already running and record it — see `compareRealmHash`'s comment.
      writeRealmHash(instance, renderedRealm);
    } else {
      // 'ok' — matches what Keycloak already imported. Nothing to do.
    }
  }

  const reattached = await ensureProxy({ repoRoot: REPO_ROOT, proxyPort, exec: run });
  if (reattached.length > 0) {
    console.log(`\nReattached to the recreated shared proxy: ${reattached.join(', ')}`);
    const stale = staleReattachedInstances(reattached, proxyPort);
    const warning = staleReattachedWarning(stale);
    if (warning) {
      console.warn(warning);
    }
  }
  // Only once the proxy is up: the dev-server blocks proxy to an address only the running proxy
  // can name (see proxy.mjs's `hostGatewayIpv4`). `attachInstance` installs the file later on.
  const devServerHost = await hostGatewayIpv4({ exec: run });
  renderNginxConf({ repoRoot: REPO_ROOT, instance, devServerPorts: ports, devServerHost, proxyPort });

  console.log('');
  await runStep({
    pending: 'Installing frontend dependencies',
    done: 'Installed frontend dependencies',
    logFile: logFileFor(instance, 'pnpm-install'),
    run: (logFile) => runCaptured('pnpm', ['install'], { cwd: join(REPO_ROOT, 'app'), logFile }),
  });

  // Started before the containers rather than after them: compiling three Angular apps and building
  // the backend image are entirely independent, and each takes minutes. Run them one after the
  // other and a cold `just up` pays for both; started here, the frontends compile while docker
  // works, and by the time the containers are healthy the dev servers usually already are too.
  //
  // They print nothing — their output is captured — so the container steps below still read as a
  // plain sequence rather than interleaving with Vite.
  // Each one is polled from here on too, so its ready time is its own rather than the length of the
  // container phase.
  const devServers = options.detach
    ? null
    : await startDevServers({
        repoRoot: REPO_ROOT,
        instance,
        ports,
        selection: options.apps,
        spawnProcess: spawnResolved,
      });
